        #1 0x7f9c13c60b01 in g_variant_byteswap ../glib/gvariant.c:6211
        #2 0x564ae412e9b9 in test_byteswap ../glib/tests/gvariant.c:2321
        #3 0x564ae412e9b9 in test_byteswaps ../glib/tests/gvariant.c:2374
